let sentAt=0;const REDUCED=matchMedia('(prefers-reduced-motion: reduce)');
const newKey=()=>'game-'+Array.from(crypto.getRandomValues(new Uint8Array(10)),b=>b.toString(16).padStart(2,'0')).join('');
async function send(game,gid,payload){const chat=C();if(!chat||typeof chat.sendGame!=='function'){toast('Spelletjes werken hier nog niet.');return false}
 try{await chat.sendGame({game,gid,payload},{key:newKey()});sentAt=Date.now();return true}
 catch(e){toast(e&&e.code==='game_rate'?'Even rustig aan, probeer het zo nog eens.':e&&e.code==='game_too_big'?'Die run is te lang om te versturen.':e&&e.code==='date_poll_closed'?'De chat is gesloten.':'Versturen lukte niet. Probeer het zo nog eens.');return false}}

/* ---- Hop: runs are delta-encoded press/release frames; every client re-simulates them (ghosts + honest scores) */
const enc=a=>a.map((f,i)=>i?f-a[i-1]:f),dec=a=>{let s=0;return a.map(d=>s+=d)};
const VERIFY=new Map();
function verified(m){if(VERIFY.has(m.id))return VERIFY.get(m.id);const frames=dec(m.payload.frames||[]),s=hopRun(m.payload.seed,frames);
 while(!s.dead)hopStep(s,ghostHeld(s));const v={name:m.name||'?',self:!!m.self,score:s.score,frames,seed:m.payload.seed};VERIFY.set(m.id,v);return v}
function hopRuns(){return games().filter(m=>m.game==='hop'&&m.payload&&m.payload.seed===hopSeed()).map(verified)}
function bestPer(){const by=new Map();for(const r of hopRuns()){const k=r.self?'\u0000me':r.name;const b=by.get(k);if(!b||r.score>b.score)by.set(k,r)}return by}
function ghostList(){const by=bestPer(),out=[];for(const [k,r] of by)if(k!=='\u0000me')out.push({name:r.name,score:r.score,frames:r.frames});
 out.sort((a,b)=>b.score-a.score);const g=out.slice(0,4);const mine=by.get('\u0000me');if(mine)g.push({name:'jouw beste',score:mine.score,frames:mine.frames});return g}

/* ---- Pool: the gid's messages, folded. Players = the first two distinct authors; the last turn's end state is the truth */
const toArr=B=>{const a=Array(16).fill(null);for(const b of B)if(!b.in)a[b.id]=[+b.x.toFixed(1),+b.y.toFixed(1)];return a};
const fromArr=a=>a.map((p,id)=>p?{id,x:p[0],y:p[1],vx:0,vy:0,in:false}:{id,x:-50,y:-50,vx:0,vy:0,in:true});
function poolGame(gid){const turns=games().filter(m=>m.game==='pool'&&m.gid===gid).sort((a,b)=>a.seq-b.seq);if(!turns.length)return null;
 const players=[];for(const m of turns){const key=m.self?'\u0000me':m.name;if(!players.some(p=>p.key===key)&&players.length<2)players.push({key,name:m.self?'jij':m.name,self:!!m.self})}
 const last=turns[turns.length-1],P=last.payload;let me=players.findIndex(p=>p.self);if(me<0&&players.length<2)me=1;
 const opp=players[1-Math.max(0,me)]||null;
 return {gid,turns,players,me,opp,last,balls:fromArr(P.end),turn:P.turn,groups:P.groups.slice(),over:P.over,myTurn:me>=0&&P.over===null&&P.turn===me,lastBySomeoneElse:!last.self}}
function judge(st,B,ev,who){const other=1-who,pk=ev.pocketed.filter(id=>id!==0),scratch=ev.pocketed.includes(0);let over=null,cont=false,note='';
 if(pk.includes(8)){const g=st.groups[who];over=(g&&left(B,g)===0&&!scratch)?who:other;note=over===who?'de 8 erin!':'de 8 te vroeg…'}
 else{if(!st.groups[who]){const f=pk.find(id=>id!==8);if(f){st.groups[who]=groupOf(f);st.groups[other]=groupOf(f)==='hele'?'halve':'hele'}}
  const g=st.groups[who],mine=pk.filter(id=>g?groupOf(id)===g:true);cont=!scratch&&mine.length>0;note=scratch?'wit erin (fout)':pk.length?pk.length+' gepot':'mis'}
 if(scratch&&over===null){const c=B.find(b=>b.id===0);c.in=false;c.x=100;c.y=272;for(let k=0;k<30&&B.some(b=>b!==c&&!b.in&&Math.hypot(b.x-c.x,b.y-c.y)<2*PT.r+1);k++)c.x=100+((k%2)?1:-1)*(k+1)*4}
 st.balls=B;st.over=over;st.turn=over!==null?other:cont?who:other;return {note,cont,over,pk,scratch}}

/* ---- game messages (eggs.js calls makeCard for kind 'game'). Chris: "the message shouldn't look special, all should look really
   native". So: an ordinary chat bubble (same classes as text, so runs group the same way), a rounded picture, a bold "Biljart?",
   one grey line. Tap anywhere on it to play. The picture is drawn once from that message's own payload. */
const CARDS=new Map(),TW=220,TH=130,TITLE={hop:'Pudding Hop?',pool:'Biljart?'};
const clockOf=at=>{try{return new Intl.DateTimeFormat('nl-NL',{timeZone:'Europe/Amsterdam',hour:'2-digit',minute:'2-digit'}).format(new Date(at))}catch{return ''}};
function makeCard(m){const el=document.createElement('div');el.className='msg eg-cm gm-msg '+(m.self?'out':'in');el.setAttribute('role','button');el.tabIndex=0;
 if(!m.self){if(m.avatar){const a=document.createElement('img');a.className='eg-av';a.alt='';a.src=m.avatar;el.append(a)}const f=document.createElement('div');f.className='from';f.textContent=m.name||'?';f.style.color=nameCol(m.name||'?');el.append(f)}
 const cv=document.createElement('canvas');cv.className='gm-th';cv.width=TW;cv.height=TH;cv.setAttribute('aria-hidden','true');
 const bd=document.createElement('div');bd.className='gm-bd';const ti=document.createElement('b');ti.className='gm-ti';ti.textContent=TITLE[m.game]||'Spel?';
 const sub=document.createElement('span');sub.className='gm-sub';const t=document.createElement('span');t.className='t';t.textContent=m.t||clockOf(m.at);
 if(m.self){const k=document.createElement('b');k.textContent='✓✓';t.append(' ',k)}
 bd.append(ti,sub,t);el.append(cv,bd);
 const cd={el,cv,sub,m};CARDS.set(m.id,cd);
 const go=()=>open(cd);el.addEventListener('click',go);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}});
 el._play=()=>el.classList.add('pop2');
 if(m.self&&Date.now()-sentAt<8000){sentAt=0;requestAnimationFrame(()=>el.isConnected&&el.scrollIntoView({block:'end',behavior:REDUCED.matches?'auto':'smooth'}))}
 subtitle(cd);thumb(cv,m);return el}
function subtitle(cd){const m=cd.m;let s='';
 if(m.game==='hop'){const v=verified(m);s=m.self?'Jouw run: '+v.score:(m.name||'?')+': '+v.score+' · verslaan?'}
 else{const g=poolGame(m.gid);
  s=!g?'':g.over!==null?(g.players[g.over]?(g.players[g.over].self?'Jij hebt gewonnen':g.players[g.over].name+' heeft gewonnen'):'Afgelopen')
   :g.players.length<2&&g.me===0?'Wacht op een tegenspeler':g.myTurn?'Jouw beurt':'Beurt van '+((g.players[g.turn]||{}).name||'de ander')}
 cd.sub.textContent=s;cd.el.setAttribute('aria-label',(TITLE[m.game]||'Spel?')+' '+s)}
// the pictures: notebook ink on paper, still (no boil in the chat)
function thumb(cv,m){const c=cv.getContext('2d'),f=FRAME;FRAME=0;
 try{c.setTransform(1,0,0,1,0,0);c.fillStyle='#fff';c.fillRect(0,0,TW,TH);if(m.game==='hop')thumbHop(c,m);else thumbPool(c,m)}finally{FRAME=f}}
// notebook paper, a shade off white, so the picture keeps its edge inside a white bubble
function paper(c){const im=c.getImageData(0,0,TW,TH),d=im.data;for(let i=0;i<d.length;i+=4)if(d[i]===255&&d[i+1]===255&&d[i+2]===255){d[i]=248;d[i+1]=246;d[i+2]=240}c.putImageData(im,0,0)}
function thumbHop(c,m){const G=110,p=pen(c,hashStr('th:'+(m.id||'hop')));
 p.line([[-4,G],[80,G+.6],[150,G],[226,G+.6]],'#111',1.5,.7);
 for(let i=0;i<8;i++){const x=10+i*28+p.j(8);p.line([[x,G+8],[x+7+p.j(4),G+8]],'#111',1.1,.3)}
 c.setTransform(1,0,0,1,0,G-HOP.G);drawObs(pen(c,5),{k:'reel',w:32,h:32,x:40,id:3},117);c.setTransform(1,0,0,1,0,0);
 cat(pen(c,9),133,G-44,.66,{rot:-.16});                                   // the pudding, mid-hop over the reel
 for(const [y,x,l] of [[G-78,76,18],[G-66,70,24],[G-54,80,14]])p.line([[x,y],[x+l,y]],'#111',1.3,.4);   // speed lines
 ink3(c,TW,TH);paper(c)}
function thumbPool(c,m){const p=pen(c,hashStr('th:'+(m.id||'pool'))),x0=8,y0=8,x1=212,y1=122,cx=(x0+x1)/2;
 p.line([[x0,y0],[x1,y0],[x1,y1],[x0,y1]],'#111',1.8,.6,true);
 p.line([[x0+7,y0+7],[x1-7,y0+7],[x1-7,y1-7],[x0+7,y1-7]],'#111',1,.4,true);
 for(const [x,y] of [[x0+7,y0+7],[cx,y0+5],[x1-7,y0+7],[x0+7,y1-7],[cx,y1-5],[x1-7,y1-7]])p.dot(x,y,4.6,'#111');
 const hs=x0+7+(PT.y1-272)/(PT.y1-PT.y0)*(x1-x0-14);for(let y=y0+14;y<y1-12;y+=7)p.line([[hs,y],[hs,y+3]],'#111',1,.2);   // head string
 ink3(c,TW,TH);paper(c);
 // balls in colour on top: the table's long side runs left to right, the rack on the right
 const sx=(x1-x0-14)/(PT.y1-PT.y0),sy=(y1-y0-14)/(PT.x1-PT.x0),R=Math.max(3.4,PT.r*Math.min(sx,sy));
 c.lineWidth=1;(m.payload.end||[]).forEach((b,id)=>{if(!b)return;const X=x1-7-(b[1]-PT.y0)*sx,Y=y0+7+(b[0]-PT.x0)*sy,col=BALLCOL[id];
  c.save();c.beginPath();c.arc(X,Y,R,0,7);c.fillStyle=id>8||id===0?'#fff':col;c.fill();
  if(id>8){c.clip();c.fillStyle=col;c.fillRect(X-R,Y-R*.45,2*R,R*.9)}c.restore();
  c.beginPath();c.arc(X,Y,R,0,7);c.strokeStyle='#111';c.stroke()})}
function refreshAll(){for(const cd of CARDS.values()){if(!cd.el.isConnected){CARDS.delete(cd.m.id);continue}subtitle(cd)}}
setInterval(()=>{if(!still)FRAME++;if(OV&&OV.tick12)OV.tick12()},83);

/* ---- the game drawer: a sheet that slides up over the chat (the chat stays visible, dimmed, behind it), like a game
   opened from a message in any phone chat. Close: ×, Escape, tapping the dimmed chat, or swiping the handle down. */
const dim=document.createElement('div');dim.className='gm-dim';dim.hidden=true;
const ov=document.createElement('div');ov.className='gm-ov';ov.hidden=true;ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');
ov.innerHTML='<div class="gm-grab" aria-hidden="true"><span></span></div><div class="gm-head"><div class="gm-hd"><b class="gm-ovt"></b><small class="gm-ovs"></small></div>'+
 '<button class="gm-x" aria-label="Sluiten"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 6.4 17.6 5 12 10.6 6.4 5 5 6.4 10.6 12 5 17.6 6.4 19 12 13.4 17.6 19 19 17.6 13.4 12z"/></svg></button></div><div class="gm-stage"></div>';
document.body.append(dim,ov);const stage=ov.querySelector('.gm-stage');let OV=null,closing=0;
ov.setAttribute('aria-labelledby','gm-ovt');ov.querySelector('.gm-ovt').id='gm-ovt';
// desktop: the drawer covers the chat pane only (the composer bar spans exactly that pane)
function place(){const f=document.querySelector('.foot'),r=f&&innerWidth>=900?f.getBoundingClientRect():null,on=!!(r&&r.width);
 Object.assign(ov.style,on?{left:r.left+'px',width:r.width+'px'}:{left:'',width:''});dim.style.left=on?r.left+'px':''}
function openOv(title,sub,mod){if(OV)closeOv(true);clearTimeout(closing);ov.querySelector('.gm-ovt').textContent=title;ov.querySelector('.gm-ovs').textContent=sub||'';
 stage.replaceChildren();place();ov.style.transform='';ov.hidden=dim.hidden=false;OV=mod;mod.mount(stage);
 const on=()=>{ov.classList.add('on');dim.classList.add('on')};if(still)on();else{void ov.offsetHeight;requestAnimationFrame(on)}
 ov.querySelector('.gm-x').focus({preventScroll:true})}
// after a game closes: one re-read, so a waiting player sees the other's move soon (the page throttles it)
function closeOv(now){if(!OV&&ov.hidden)return;if(OV&&OV.unmount)OV.unmount();OV=null;ov.classList.remove('on','drag');dim.classList.remove('on');ov.style.transform='';
 const done=()=>{if(OV)return;ov.hidden=dim.hidden=true;stage.replaceChildren()};clearTimeout(closing);if(now===true||still)done();else closing=setTimeout(done,280);
 const chat=C();if(chat&&typeof chat.refresh==='function')try{chat.refresh()}catch{}}
dim.addEventListener('click',()=>closeOv());ov.querySelector('.gm-x').addEventListener('click',()=>closeOv());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&OV)closeOv()});
{let y0=null,dy=0;for(const h of [ov.querySelector('.gm-grab'),ov.querySelector('.gm-head')]){
 h.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;y0=e.clientY;dy=0;try{h.setPointerCapture(e.pointerId)}catch{}ov.classList.add('drag')});
 h.addEventListener('pointermove',e=>{if(y0===null)return;dy=Math.max(0,e.clientY-y0);ov.style.transform='translateY('+dy+'px)'});
 const up=()=>{if(y0===null)return;y0=null;ov.classList.remove('drag');if(dy>80)closeOv();else ov.style.transform=''};
 h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up)}}
// a game canvas as big as the drawer allows, keeping its pixels square
function fitCanvas(cv,W,H,reserve){const k=Math.max(.6,Math.min((stage.clientWidth-24)/W,(stage.clientHeight-reserve)/H));cv.style.width=Math.floor(W*k)+'px';cv.style.height=Math.floor(H*k)+'px'}
function open(cd){const m=cd.m;if(m.game==='hop'){openOv('Pudding Hop','Dezelfde baan voor iedereen',hopModule());return}
 const g=poolGame(m.gid);if(!g)return;if(g.over!==null){challenge();return}
 if(!g.myTurn&&!(g.lastBySomeoneElse&&g.last.id===m.id)){toast('Beurt van '+((g.players[g.turn]||{}).name||'de ander'));return}
 openOv('Biljart',g.opp?'Tegen '+g.opp.name:'',poolModule(g))}

/* ---- Hop module: today's course (the same for everyone in this poll), your friends' best runs as ghosts */
function hopModule(){const SEED=hopSeed();let fit,cv,cx,panel,hint,sim,ghosts,rec,held,phase,raf=0,acc=0,last=0,deadAt=0,flash=null,passed,next='';
 function reset(){sim=hopRun(SEED);rec=[];held=false;phase='ready';passed=new Set();flash=null;ghosts=ghostList().map(g=>({name:g.name,score:g.score,run:hopRun(SEED,g.frames)}));panel.hidden=true;
  hint.textContent=ghosts.length?'Je racet tegen: '+ghosts.map(g=>g.name+' '+g.score).join(' · '):'Zet de eerste score neer.'}
 function start(){phase='run';last=performance.now();acc=0}
 function press(){if(phase==='ready'){start();return}if(phase==='dead'){if(performance.now()-deadAt>380){reset();start()}return}if(!held){held=true;rec.push(sim.f)}}
 function release(){if(held){held=false;if(phase==='run')rec.push(sim.f)}}
 function die(){phase='dead';deadAt=performance.now();if(held){rec.push(sim.f);held=false}if(rec.length%2)rec.push(sim.f);
  const all=[{name:'jij',score:sim.score,me:true},...ghosts.filter(g=>g.name!=='jouw beste').map(g=>({name:g.name,score:g.score}))].sort((a,b)=>b.score-a.score),rank=all.findIndex(x=>x.me)+1;
  setTimeout(()=>{if(phase!=='dead')return;panel.hidden=false;const r=panel.querySelector('.gm-rank');r.replaceChildren();
   all.forEach((x,i)=>{const d=document.createElement('div');d.textContent=(i+1)+'. '+x.name+' · '+x.score;if(x.me)d.className='me';r.append(d)});
   hint.textContent='#'+rank+' van '+all.length+(rank===1&&all.length>1?' · jij staat bovenaan':'')},380)}
 function frame(ts){raf=requestAnimationFrame(frame);
  if(phase==='run'){acc+=Math.min(.1,(ts-last)/1000);last=ts;
   while(acc>=HOP.DT){acc-=HOP.DT;hopStep(sim,held);for(const g of ghosts)hopStep(g.run,ghostHeld(g.run));
    for(const g of ghosts){if(g.run.dead&&!passed.has(g.name)&&sim.score>g.run.score){passed.add(g.name);flash={t:g.name+' ingehaald!',n:70}}}
    if(sim.dead){die();break}}}
  const up=ghosts.filter(g=>g.score>sim.score).sort((a,b)=>a.score-b.score)[0];next=up?'volgende: '+up.name+' '+up.score:(ghosts.length?'je staat vooraan':'');
  hopDraw(cx,{player:sim,ghosts,phase,flash,next,showRetry:phase==='dead'&&performance.now()-deadAt>380})}
 const kd=e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW'){e.preventDefault();if(!e.repeat)press()}},ku=e=>{if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')release()};
 return {mount(st){const pap=document.createElement('div');pap.className='gm-paper';cv=document.createElement('canvas');cv.className='gm-hopc gm-cv';cv.width=HOP.W;cv.height=HOP.H;pap.append(cv);cx=cv.getContext('2d');
   hint=document.createElement('p');hint.className='gm-hint';panel=document.createElement('div');panel.className='gm-panel';
   panel.innerHTML='<div class="gm-rank"></div><div class="gm-row"><button class="gm-btn gm-send">Stuur je run</button><button class="gm-btn gm-ghost">Opnieuw</button></div>';
   st.append(pap,hint,panel);
   st.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();press()});st.addEventListener('pointerup',release);st.addEventListener('pointercancel',release);st.addEventListener('pointerleave',release);
   addEventListener('keydown',kd);addEventListener('keyup',ku);
   panel.querySelector('.gm-ghost').onclick=()=>{reset();start()};
   panel.querySelector('.gm-send').onclick=async e=>{const b=e.currentTarget;b.disabled=true;const ok=await send('hop',hopGid(),{seed:SEED,frames:enc(rec),score:sim.score});b.disabled=false;if(ok)closeOv()};
   fit=()=>fitCanvas(cv,HOP.W,HOP.H,190);fit();addEventListener('resize',fit);
   reset();raf=requestAnimationFrame(frame)},
  unmount(){cancelAnimationFrame(raf);removeEventListener('keydown',kd);removeEventListener('keyup',ku);removeEventListener('resize',fit)},
  test:{press,release,sim:()=>sim,state:()=>({phase,score:sim.score,f:sim.f,dead:sim.dead,ghosts:ghosts.map(g=>[g.name,g.run.score,g.run.dead])})}}}

/* ---- Pool module: replay the other player's last turn, then (if it's yours) aim and shoot; one message per turn */
function poolModule(g){const st={balls:cloneB(g.balls),groups:g.groups.slice(),turn:g.turn,over:g.over};let fit;
 const spectator=g.me<0;let me=spectator?-1:g.me;let cv,cx,hint,raf=0,phase='idle',aim=null,drag=null,anim=null,turnShots=[],turnStart=null,notes=[];
 const oppName=()=>(g.opp&&g.opp.name)||'de ander';
 const status=()=>{if(spectator){hint.textContent='Je kijkt mee: '+g.players.map(p=>p.name).join(' tegen ');return}const mine=st.groups[me];hint.textContent=st.over!==null?(st.over===me?'Jij wint! 🎱':oppName()+' wint 🎱'):st.turn===me?'Jij'+(mine?' ('+mine+')':'')+': sleep naar achteren om te mikken, loslaten = stoot':oppName()+' is aan de beurt'};
 const render=()=>drawPool(cx,st,phase==='aim'&&aim?aim:null);
 function toCanvas(e){const r=cv.getBoundingClientRect();return [(e.clientX-r.left)/r.width*PT.W,(e.clientY-r.top)/r.height*PT.H]}
 function animate(shot,done){anim={B:cloneB(st.balls),ev:{pocketed:[],first:null}};shoot(anim.B,shot);const vis={...st,balls:anim.B};
  const tick=()=>{for(let k=0;k<SUB;k++)poolStep(anim.B,PDT,anim.ev);drawPool(cx,vis,null);if(moving(anim.B))raf=requestAnimationFrame(tick);else{for(const b of anim.B)b.vx=b.vy=0;const a=anim;anim=null;done(a)}};raf=requestAnimationFrame(tick)}
 function endTurn(){phase='sending';hint.textContent='versturen…';
  const payload={shots:turnShots,start:toArr(turnStart),end:toArr(st.balls),turn:st.turn,groups:st.groups.slice(),over:st.over};
  send('pool',g.gid,payload).then(ok=>{if(ok)setTimeout(closeOv,500);else{phase='idle';status()}})}
 // a turn starts from the wire state (1 decimal), so the other side replays it exactly: a racked break is chaotic, a 0.05 nudge changes everything
 function myShot(shot){if(!turnStart){st.balls=fromArr(toArr(st.balls));turnStart=cloneB(st.balls)}turnShots.push(shot);phase='anim';hint.textContent='…';
  animate(shot,({B,ev})=>{const res=judge(st,B,ev,me);notes.push(res.note);render();status();
   if(st.turn===me&&st.over===null&&turnShots.length<8){phase='aim';if(res.pk.length)toast(res.note+' · nog een keer!');return}
   if(st.turn===me&&st.over===null)st.turn=1-me;// at most 8 shots per turn: then it's the other's go
   endTurn()})}
 function replay(done){const P=g.last.payload;st.balls=fromArr(P.start);render();hint.textContent=(g.last.name||'de ander')+' stoot…';let i=0;
  const nextShot=()=>{if(i>=P.shots.length){st.balls=fromArr(P.end);st.groups=P.groups.slice();st.turn=P.turn;st.over=P.over;render();done();return}
   animate(P.shots[i++],({B})=>{st.balls=B;render();setTimeout(nextShot,450)})};setTimeout(nextShot,500)}
 return {mount(el){const pap=document.createElement('div');pap.className='gm-paper';cv=document.createElement('canvas');cv.className='gm-poolc gm-cv';cv.width=PT.W;cv.height=PT.H;pap.append(cv);cx=cv.getContext('2d');hint=document.createElement('p');hint.className='gm-hint';el.append(pap,hint);fit=()=>fitCanvas(cv,PT.W,PT.H,64);fit();addEventListener('resize',fit);
   cv.addEventListener('pointerdown',e=>{if(phase!=='aim')return;e.preventDefault();try{cv.setPointerCapture(e.pointerId)}catch{}drag=toCanvas(e);aim=null});
   cv.addEventListener('pointermove',e=>{if(!drag||phase!=='aim')return;const [x,y]=toCanvas(e);let dx=drag[0]-x,dy=drag[1]-y;const L=Math.hypot(dx,dy);if(L<3){aim=null;render();return}aim={dx:dx/L,dy:dy/L,p:Math.min(1,L/110)};render();hint.textContent='kracht '+Math.round(aim.p*100)+'%'});
   const up=()=>{if(!drag)return;drag=null;if(phase==='aim'&&aim&&aim.p>.04){const s={dx:+aim.dx.toFixed(4),dy:+aim.dy.toFixed(4),p:+aim.p.toFixed(3)};aim=null;myShot(s)}else{aim=null;render();status()}};
   cv.addEventListener('pointerup',up);cv.addEventListener('pointercancel',up);
   render();const go=()=>{phase=!spectator&&st.over===null&&st.turn===me?'aim':'idle';status();render()};
   if(g.lastBySomeoneElse&&g.last.payload.shots.length&&!g.fresh){phase='replay';replay(go)}else go()},
  unmount(){cancelAnimationFrame(raf);removeEventListener('resize',fit)},
  tick12(){if(phase==='aim'||phase==='idle')render()},
  test:{shoot:(dx,dy,p)=>{if(phase==='aim')myShot({dx,dy,p})},state:()=>({phase,turn:st.turn,me,over:st.over,groups:st.groups,inPlay:st.balls.filter(b=>!b.in).length})}}}
