for(const T of [{k:'hop',t:'Pudding Hop',bg:'#ff2e74'},{k:'pool',t:'Biljart',bg:'#1fa855'}]){const b=document.createElement('button');b.className='gm-tile';b.setAttribute('role','menuitem');
 const ic=document.createElement('span');ic.className='gm-ic';ic.style.background=T.bg;ic.innerHTML=ICONS[T.k];const lb=document.createElement('span');lb.textContent=T.t;b.append(ic,lb);
 b.onclick=()=>{toggleSheet(false);if(T.k==='hop')openOv('Pudding Hop','Dezelfde baan voor iedereen',hopModule());else challenge()};sheet.append(b)}
function allowed(){return document.body.classList.contains('voted')&&!!LIST.canSend}
function toggleSheet(on){if(on&&!allowed()){toast('Stem eerst, dan kun je spelen.');on=false}
 // desktop: just above the + in the chat pane
 const fi=document.querySelector('.fi svg:first-child'),r=fi&&innerWidth>=900?fi.getBoundingClientRect():null;
 Object.assign(sheet.style,r&&r.width?{left:Math.max(8,r.left-8)+'px'}:{left:''});
 sheet.hidden=!on;document.body.classList.toggle('gm-sheet-open',on)}
document.addEventListener('pointerdown',e=>{if(!sheet.hidden&&!sheet.contains(e.target)&&!e.target.closest('.gm-plus,.fi svg:first-child'))toggleSheet(false)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!sheet.hidden)toggleSheet(false)});
function wirePlus(){const fi=document.querySelector('.fi svg:first-child');if(fi&&!fi._gm){fi._gm=1;fi.classList.add('gm-tap');fi.addEventListener('click',()=>toggleSheet(sheet.hidden))}
 const foot=document.querySelector('.foot-in');if(foot&&!foot.querySelector('.gm-plus')){const b=document.createElement('button');b.className='gm-plus';b.setAttribute('aria-label','Spelletjes');
  b.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5h2v6h6v2h-6v6h-2v-6H5v-2h6z"/></svg>';b.onclick=()=>toggleSheet(sheet.hidden);foot.prepend(b)}}

